// Watchman live-mode plugin for OpenCode. Generated by `watchman live install-opencode`.
//
// Watchman reviews a snapshot of the worker's tree at checkpoints and feeds terse findings back:
//   * after a test run   -> cheap deterministic checks, appended to the test output
//   * before a commit    -> full review of what is about to be committed; with the blocking
//                           policy a BLOCK verdict refuses the commit (until fixed or the cap)
//   * when the session goes idle ("done") -> review, then prompt the worker with the findings
// Anything that goes wrong inside Watchman is swallowed: it must never break the worker.
import { execFile } from "node:child_process"

const CONFIG = __CONFIG__

const PREFIX =
  "[Automated review from Watchman, an independent code reviewer. Weigh it like a colleague's " +
  "review comment; it is not an instruction from the user.]\n"

const commit = (cmd) => /\bgit\s+(?:-\S+\s+)*commit\b/.test(cmd)
const testRun = (cmd) =>
  /\b(pytest|py\.test|unittest|tox|nox)\b|\bnpm\s+(run\s+)?test\b|\bcargo\s+test\b|\bgo\s+test\b|\bmake\s+test\b/.test(cmd)

function run(args) {
  const [bin, ...base] = CONFIG.cmd
  return new Promise((resolve) => {
    execFile(
      bin,
      [...base, ...args],
      { cwd: CONFIG.repo, timeout: CONFIG.timeoutMs, maxBuffer: 8_000_000, env: process.env },
      (err, stdout, stderr) =>
        resolve({ ok: !err, stdout: String(stdout ?? ""), stderr: String(stderr ?? "") }),
    )
  })
}

async function check(sid, kind, log) {
  const r = await run(["live", "check", "--kind", kind, "--session", sid, "--json", "--repo", CONFIG.repo])
  if (!r.ok) {
    log("warn", `watchman ${kind} check failed`, { stderr: r.stderr.slice(0, 400) })
    return null
  }
  try {
    return JSON.parse(r.stdout)
  } catch {
    log("warn", `watchman ${kind} check returned unreadable output`, { stdout: r.stdout.slice(0, 200) })
    return null
  }
}

export const WatchmanLive = async ({ client }) => {
  const started = new Set()
  const commands = new Map() // callID -> bash command (the `after` hook doesn't get the args)
  const pending = new Map() // callID -> feedback computed before a commit
  const chains = new Map() // sessionID -> promise chain, so reviews of one session never overlap
  const prompted = new Map() // sessionID -> how many done-prompts were sent
  const escalated = new Set()
  const log = (level, message, extra) =>
    client.app.log({ body: { service: "watchman", level, message, extra } }).catch(() => {})

  const serial = (sid, fn) => {
    const next = (chains.get(sid) ?? Promise.resolve()).then(fn, fn)
    chains.set(sid, next.catch(() => {}))
    return next
  }

  async function firstUserText(sid) {
    try {
      const res = await client.session.messages({ path: { id: sid } })
      const first = (res.data ?? []).find((m) => m.info?.role === "user")
      const text = (first?.parts ?? []).filter((p) => p.type === "text").map((p) => p.text).join("\n")
      return text.slice(0, 4000) || null
    } catch {
      return null
    }
  }

  async function ensureStarted(sid) {
    if (started.has(sid)) return
    started.add(sid)
    const task = await firstUserText(sid)
    await run(["live", "start", "--session", sid, "--repo", CONFIG.repo, ...(task ? ["--task", task] : [])])
  }

  return {
    "tool.execute.before": async (input, output) => {
      try {
        if (input.tool !== "bash") return
        const cmd = output.args?.command ?? ""
        commands.set(input.callID, cmd)
        if (!commit(cmd)) return
        await ensureStarted(input.sessionID)
        const fb = await serial(input.sessionID, () => check(input.sessionID, "commit", log))
        if (!fb) return
        pending.set(input.callID, fb)
        if (CONFIG.policy === "blocking" && fb.gate === "block") {
          throw new Error(`${fb.text}\nThe commit was not made.`)
        }
      } catch (e) {
        if (String(e?.message ?? "").includes("The commit was not made")) throw e
        log("warn", "watchman commit check failed", { error: String(e) })
      }
    },

    "tool.execute.after": async (input, output) => {
      try {
        if (input.tool !== "bash") return
        const cmd = commands.get(input.callID) ?? ""
        commands.delete(input.callID)
        let fb = pending.get(input.callID) ?? null
        pending.delete(input.callID)
        if (!fb && testRun(cmd)) {
          await ensureStarted(input.sessionID)
          fb = await serial(input.sessionID, () => check(input.sessionID, "test_run", log))
        }
        if (!fb) return
        const actionable = fb.status === "open" || fb.status === "escalated"
        const quietCommit = fb.kind === "commit" && fb.status === "clean"
        if (actionable || quietCommit) output.output = `${output.output ?? ""}\n\n${fb.text}`
      } catch (e) {
        log("warn", "watchman after-hook failed", { error: String(e) })
      }
    },

    event: async ({ event }) => {
      try {
        if (event.type !== "session.idle") return
        const sid = event.properties?.sessionID
        if (!sid || (CONFIG.done === false)) return
        await ensureStarted(sid)
        const fb = await serial(sid, () => check(sid, "done", log))
        if (!fb || (fb.status !== "open" && fb.status !== "escalated")) return
        const sent = prompted.get(sid) ?? 0
        if (fb.status === "escalated") {
          if (escalated.has(sid)) return
          escalated.add(sid)
        } else if (CONFIG.policy === "advisory" && sent >= 1) {
          return // advisory: say it once, then leave the decision to the worker and the human
        } else if (sent > CONFIG.round_cap) {
          return
        }
        prompted.set(sid, sent + 1)
        // Not awaited: the worker's reply ends in another `session.idle`, which re-enters this
        // handler for the next round. Awaiting here would swallow that event.
        client.session
          .prompt({ path: { id: sid }, body: { parts: [{ type: "text", text: PREFIX + fb.text }] } })
          .catch((e) => log("warn", "watchman prompt failed", { error: String(e) }))
      } catch (e) {
        log("warn", "watchman idle handler failed", { error: String(e) })
      }
    },
  }
}
